  USING ( SELECT 'DMF0082_version_SEARCH' AS API_ID, 'PROC_SELECT' AS API_TP_CD, 'MSG_API_DMF0082_version_SEARCH' AS API_MSG_ID, 'DMF0082 Version 팝업 조회 (DMF0073 공유 계약)' AS API_MSG_DESC, 'DMF0073_GET_VERSION_SALESPRICE' AS API_URL, 'Y' AS USE_YN, 'admin' AS CREATED_BY, TO_DATE('2026-07-12 12:34:11','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'admin' AS LAST_UPDATED_BY, TO_DATE('2026-07-12 12:34:11','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL ) S
     ON ( T.API_ID = S.API_ID )
   WHEN MATCHED THEN UPDATE SET T.API_TP_CD = S.API_TP_CD, T.API_MSG_ID = S.API_MSG_ID, T.API_MSG_DESC = S.API_MSG_DESC, T.API_URL = S.API_URL, T.USE_YN = S.USE_YN, T.LAST_UPDATED_BY = 'admin', T.LAST_UPDATE_DATE = SYSDATE
   WHEN NOT MATCHED THEN INSERT (API_ID, API_TP_CD, API_MSG_ID, API_MSG_DESC, API_URL, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE) VALUES (S.API_ID, S.API_TP_CD, S.API_MSG_ID, S.API_MSG_DESC, S.API_URL, S.USE_YN, S.CREATED_BY, S.CREATION_DATE, S.LAST_UPDATED_BY, S.LAST_UPDATE_DATE);
END;
/

